import { Component, ComponentInterface, Element, h, Host, Prop } from '@stencil/core';
import { Slot, Slots } from '@src/framework/decorators';

const prefix = 'nav-item-group';

/**
 * @slot title - Slot for the title text of the nav item group.
 * @slot default - Slot for the nav items and nested navigation rendered inside the group.
 * @part base - The base container of the component.
 */
@Component({
  styleUrl: 'styles/ks-nav-item-group.scss',
  tag: 'ks-nav-item-group',
  shadow: true,
})
export class KsNavItemGroup implements ComponentInterface {
  @Element() el!: HTMLKsNavItemGroupElement;

  /** The level for current nav item group. */
  @Prop() level = 0;

  @Slot({ slotname: 'title' }) private titleSlots?: Slots;

  render() {
    return (
      <Host class="KsNavItemGroup">
        <div class={prefix} style={{ '--ks-comp-side-navigation-level': `${this.level}` }} part="base">
          {this.titleSlots && (
            <div class={`${prefix}__title`}>
              <slot name="title" />
            </div>
          )}
          <slot />
        </div>
      </Host>
    );
  }
}
